#include "session.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace perekup;auto root=fs::temp_directory_path()/("perekup-async-start-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));Json cities={{"home",{{"id","home"}}}},cars=Json::object();try{Session s(root,cities,cars,"home");s.beginCreate("Игрок","TEST",1000000);assert(s.creating()&&!s.ready()&&s.state.is_null());bool rejected=false;try{s.beginCreate("Другой","ABCD",1000000);}catch(...){rejected=true;}assert(rejected);auto end=std::chrono::steady_clock::now()+std::chrono::seconds(10);while(!s.creationReady()&&std::chrono::steady_clock::now()<end)std::this_thread::yield();assert(s.creationReady());assert(s.finishCreate()&&s.ready()&&!s.creating());Session reload(root,cities,cars,"home");assert(reload.load().status==LoadStatus::Loaded);assert(reload.state["playerIdentity"]["nickname"]=="Игрок");auto log=SaveStore::read(root/"saves/native-save.log");assert(log.find("save complete")!=std::string::npos);assert(log.find("TEST")==std::string::npos&&log.find("Игрок")==std::string::npos);fs::remove_all(root);std::cout<<"PASS asynchronous first save, duplicate guard, publication after completion, reload and private diagnostics\n";}catch(...){fs::remove_all(root);throw;}}
